'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
const rooms=['S','A','B','C','D','T'],coords=[[40,140],[165,56],[165,224],[335,56],[335,224],[460,140]],edges=[['S','A'],['S','B'],['A','C'],['B','D'],['A','B'],['C','D'],['C','T'],['D','T']],banks=[[2,5,2,1,2,3,6,1],[5,1,1,5,1,2,2,5],[1,4,3,2,2,1,5,2],[3,2,5,2,1,1,1,4],[2,4,2,1,1,4,3,2],[4,2,2,3,2,1,2,3]];
let variant=OrionProgress.variant('maze'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget;
let stage=0,path=['S'],solved=false,hintDepth=0,state='ready',saveFailed=false,history=[];
function weights(v=variant,s=stage){return banks[(v+s*2)%6];}
function cost(a,b){const i=edges.findIndex(e=>e.includes(a)&&e.includes(b)&&a!==b);return i<0?Infinity:weights()[i];}
function total(p=path){return p.slice(1).reduce((sum,n,i)=>sum+cost(p[i],n),0);}
function routes(p=['S']){if(p.at(-1)==='T')return [p];return rooms.filter(n=>!p.includes(n)&&Number.isFinite(cost(p.at(-1),n))).flatMap(n=>routes([...p,n]));}
function best(){return routes().sort((a,b)=>total(a)-total(b))[0];}
function resetTrial(){path=['S'];solved=false;hintDepth=0;state='ready';saveFailed=false;history=[];$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('maze')){variant=v;stage=0;resetTrial();}
function choose(n){if(solved||path.at(-1)==='T'||!rooms.includes(n)||path.includes(n)||!Number.isFinite(cost(path.at(-1),n)))return;path.push(n);state='ready';render();focusRoute();}
function focusRoute(){const n=rooms.find(n=>!path.includes(n)&&Number.isFinite(cost(path.at(-1),n)));if(path.at(-1)==='T')$('check').focus();else if(n)$('room'+n).focus();else $('undo').focus();}
function undo(){if(solved||path.length<2)return;path.pop();state='ready';render();focusRoute();}
function check(){if(solved)return;if(path.at(-1)!=='T'){state='incomplete';render();return;}history.unshift({route:path.join(' → '),energy:total()});history=history.slice(0,3);if(total()!==total(best())){state='wrong';render();return;}solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('wisdom');render();if(stage<2)$('next').focus();}
function hints(){return[t('Add every passage number. More passages can still cost less energy!','把每條通道的數字相加。通道較多，仍可能更省能量！'),t(`The smallest possible total here is ${total(best())}. Compare another route.`,`這張地圖最小的總數是 ${total(best())}。試比較另一條路線。`),t('One least-energy route is: ','其中一條最省能量的路線是：')+best().join(' → ')];}
function render(){const complete=solved&&stage===2,count=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Heart of the Labyrinth · Orion','智慧之心的地下迷城 · Orion');$('stageTitle').textContent=t(`Seal ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 道封印 · 第 ${variant+1} 組`);$('sceneStatus').textContent=t(`Seals awakened · ${count} / 3`,`已喚醒 ${count} / 3 道封印`);$('seals').textContent=Array.from({length:3},(_,i)=>i<count?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);
$('paths').setAttribute('aria-label',t('Passage energy costs: ','通道能量成本：')+edges.map((e,i)=>e.join(' ↔ ')+': '+weights()[i]).join('; '));$('paths').innerHTML=edges.map(([a,b],i)=>{const [x,y]=coords[rooms.indexOf(a)],[u,v]=coords[rooms.indexOf(b)],used=path.some((n,j)=>j>0&&[a,b].includes(n)&&[a,b].includes(path[j-1]));return `<line class="passage ${used?'used':''}" x1="${x}" y1="${y}" x2="${u}" y2="${v}"/><circle class="cost-disc" cx="${(x+u)/2}" cy="${(y+v)/2}" r="15"/><text class="cost" x="${(x+u)/2}" y="${(y+v)/2+6}">${weights()[i]}</text>`;}).join('');
$('nodes').innerHTML=rooms.map((n,i)=>{const available=!solved&&path.at(-1)!=='T'&&!path.includes(n)&&Number.isFinite(cost(path.at(-1),n)),links=rooms.filter(m=>Number.isFinite(cost(n,m))).map(m=>m+': '+cost(n,m)).join(', ');return `<button id="room${n}" class="room ${path.at(-1)===n?'current':path.includes(n)?'visited':available?'available':''}" style="left:${coords[i][0]/5}%;top:${coords[i][1]/2.8}%" ${available?'':'disabled'} aria-label="${t('Room ','房間 ')+n+t('; connected passage costs ','；相連通道成本 ')+links}">${n}</button>`;}).join('');rooms.forEach(n=>$('room'+n).onclick=()=>choose(n));
$('goal').textContent=t('Find the least-energy route from S to T.','找出由 S 到 T 最省能量的路線。');$('reading').textContent=path.join(' → ')+t(` · Energy: ${total()}`,` · 能量：${total()}`);$('log').innerHTML=history.map(h=>`<li>${h.route} · ${h.energy}</li>`).join('');$('log').setAttribute('aria-label',t('Recent tested routes and energy totals','最近檢查的路線及能量總數'));
$('feedback').textContent={ready:t('Glowing rooms are connected to your current room. Try a route; you can undo any step.','發光的房間與目前位置相連。試一條路線；每一步都可以退回。'),incomplete:t('Reach T before checking. Tap a connected room, or undo to try another branch.','到達 T 才能檢查。點相連房間，或退回嘗試另一個分支。'),wrong:t(`Your route costs ${total()}. A cheaper route exists! Undo or clear, then compare the passage numbers.`,`你的路線用了 ${total()} 能量。還有更省的路線！退回或清空，再比較通道數字。`),success:t(`A wise route! ${total()} is the smallest energy total.`,`智慧之路！${total()} 是最小能量總數。`)}[state];
for(const id of ['check','retry','undo'])$(id).hidden=solved;$('undo').disabled=path.length===1;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('wisdom')?t('Wisdom Sigil saved in your collection.','智慧符印已存入收藏。'):'';
}
$('check').onclick=check;$('undo').onclick=undo;$('retry').onclick=()=>{if(!solved){path=['S'];state='ready';render();focusRoute();}};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();focusRoute();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('maze',variant);observedVariant=OrionProgress.variant('maze');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('wisdom');render();};
function syncProgress(){const v=OrionProgress.variant('maze'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('wisdom')&&!saveFailed)resetMission();else render();}
window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
